INSERT INTO `kunjungan` VALUES (1,'siswa','22854','2026-01-10 02:30:00','Demam tinggi disertai batuk pilek dan badan terasa sangat lemas sejak pagi hari setelah hujan deras kemarin','2026-06-27 09:14:07'),(2,'siswa','22901','2026-01-15 03:15:00','Perut mulas hebat disertai mual dan diare setelah makan siang di kantin sekolah','2026-06-27 09:14:07'),(3,'siswa','22956','2026-01-22 04:00:00','Luka gores cukup dalam di lutut kanan akibat jatuh saat bermain bola di lapangan','2026-06-27 09:14:07'),(4,'karyawan','1','2026-02-14 02:45:00','Sakit kepala berat disertai pusing dan mual setelah bekerja lama di depan komputer tanpa istirahat','2026-06-27 09:14:07'),(5,'karyawan','2','2026-03-20 03:30:00','Batuk kering terus menerus selama 4 hari disertai pilek dan sesak napas ringan','2026-06-27 09:14:07'),(6,'guru','3','2026-04-08 04:10:00','Gigi berlubang yang sangat sakit terutama saat makan dan minum air dingin sudah 1 minggu','2026-06-27 09:14:07'),(7,'guru','4','2026-05-25 02:55:00','Ruam merah gatal di kedua lengan setelah membersihkan ruang kelas yang berdebu','2026-06-27 09:14:07'),(8,'siswa','23300','2026-06-27 09:19:04','Hidung tersumbat, rasa pusing dikepala, kemarin malam itu aku kehujanan dan ga bawa jas hujan saat berkendara','2026-06-27 09:19:04'),(9,'siswa','23125','2026-06-27 09:22:14','Tenggorokan terasa gatal dan juga kering, udh diminumin kering lagi begitu terus hingga malam hari kadang sampai susah tidur','2026-06-27 09:22:14'),(10,'siswa','22873','2026-06-27 09:27:28','Mata perih dan gatal karena tadi aku garuk/sentuh terus','2026-06-27 09:27:28'),(11,'siswa','22901','2026-06-27 09:31:18','Saya merasa perut saya sakit dan mungkin karena maag saya','2026-06-27 09:31:18'),(12,'siswa','22860','2026-06-27 09:33:50','Mata saya perit karena mungkin tadi saya unyel unyel saat bermain sepak bola, apa mungkin karena debu masuk.','2026-06-27 09:33:50'),(13,'siswa','22869','2026-06-27 09:36:50','Mata saya gatal sekali. Padahal saya tidak menyentuh atau menggaruk mata secara berlebihan. Disatu sisi kulit dekat mata saya juga agak gatal.','2026-06-27 09:36:50'),(14,'siswa','23110','2026-06-27 09:40:21','Gatal ditubuh terutama ditangan. Tadi ga sengaja makan udang dan saya alergi udang','2026-06-27 09:40:21'),(15,'siswa','22877','2026-06-27 09:42:14','Tubuh saya terasa lemas dan kayak ingin ambruk, entah kenapa..','2026-06-27 09:42:14'),(16,'guru','7','2026-07-13 07:03:59','Mata saya perih tadi pagi saat pergi menuju ke sekolah, lalu saya usap dan ternyata malah memerah dan makin sakit.','2026-07-13 07:03:59'),(17,'guru','1','2026-07-22 07:02:34','Sakit tenggorokan karena semalam, kurang minum dan makan pedas','2026-07-22 07:02:34'),(18,'guru','2','2026-07-26 07:36:03','Sakit mata entah kenapa mata perih sekali, kemungkinan dikarenakan kemarin sering digosok terus karena gatal','2026-07-26 07:36:03'),(19,'guru','2','2026-07-26 07:37:57','Mata masih sakit padahal dari kemarin sudah dikasi insto tetapi tetap tidak membaik sekarang gatal sampai harus aku tutup mata, karena seperih itu.','2026-07-26 07:37:57'),(20,'guru','2','2026-07-26 07:42:14','Sebelumnya saya sudha kesini 2x dan mata saya sekarang yang dari perih sudah membaik tetapi mata saya mengkering rasanya, walau tidak segatal  dan seperih itu','2026-07-26 07:42:14'),(21,'guru','4','2026-07-29 06:05:01','Pusing tidak punya uang','2026-07-29 06:05:01'),(22,'siswa','22855','2026-08-02 05:09:33','Demam sejak pagi, badan lemas, pusing','2026-08-02 05:09:33'),(23,'siswa','22858','2026-08-02 05:10:03','Batuk pilek sudah 2 hari, tenggorokan sakit','2026-08-02 05:10:03'),(24,'siswa','22901','2026-08-02 05:12:39','Perut mulas setelah makan di kantin','2026-08-02 05:12:39'),(25,'siswa','22854','2026-08-02 05:13:45','Mata perih dan berair setelah main bola','2026-08-02 05:13:45'),(26,'siswa','23110','2026-08-02 05:15:39','Sakit gigi geraham kiri','2026-08-02 05:15:39'),(27,'siswa','23012','2026-08-02 05:16:34','Pusing dan mual di kelas','2026-08-02 05:16:34'),(28,'guru','1','2026-08-02 05:18:07','Sakit tenggorokan dan suara serak','2026-08-02 05:18:07'),(29,'guru','1','2026-08-02 05:19:26','Mata lelah dan kering','2026-08-02 05:19:26'),(30,'guru','7','2026-08-02 05:20:38','Maag kambuh, perut perih','2026-08-02 05:20:38'),(31,'guru','6','2026-08-02 05:23:40','Pusing dan leher pegal','2026-08-02 05:23:40'),(32,'guru','5','2026-08-02 05:25:39','Batuk berdahak','2026-08-02 05:25:39'),(33,'guru','3','2026-08-02 05:27:22','Alergi debu, bersin-bersin','2026-08-02 05:27:22'),(34,'karyawan','1','2026-08-02 05:29:10','Luka kecil di jari tangan','2026-08-02 05:29:10'),(35,'karyawan','2','2026-08-02 05:30:39','Sakit punggung setelah angkat barang','2026-08-02 05:30:39'),(36,'karyawan','6','2026-08-02 05:32:14','Demam ringan dan lemas','2026-08-02 05:32:14'),(39,'siswa','22854','2026-08-13 06:24:47','Mata memerah, perih dan gatal','2026-08-13 06:24:47'),(41,'siswa','22881','2026-08-13 07:02:52','Sakit perut','2026-08-13 07:02:52'),(42,'siswa','22912','2026-08-25 12:33:57','.','2026-08-25 12:33:57');
