INSERT INTO `pemeriksaan_klinis` VALUES (1,1,'Pasien demam karena terkena hujan dan kurang istirahat.','Istirahat di UKS','Flu',1),(2,2,'Kemungkinan keracunan makanan atau masuk angin. Diminta observasi selama 45 menit.','Dipulangkan','Mual',4),(3,3,'Luka dibersihkan dan diobati. Disarankan jaga kebersihan dan hindari aktivitas berlari dulu.','Kembali melanjutkan aktivitas','Luka',5),(4,4,'Kelelahan akibat beban kerja tinggi. Diberi obat pereda sakit kepala dan disarankan istirahat.','Istirahat di UKS','Sakit Kepala',1),(5,5,'Gejala ISPA ringan. Disarankan banyak istirahat dan minum vitamin C.','Dipulangkan','ISPA',3),(6,6,'Diberi obat pereda nyeri sementara. Sangat disarankan segera ke dokter gigi.','Dipulangkan','Sakit Gigi',8),(7,7,'Reaksi alergi terhadap debu. Diberi obat antihistamin dan saran pakai masker saat membersihkan.','Dipulangkan','Alergi',9),(8,8,'Hidun tersumbat, rasa pusing dikepala, ditambah suhu tubuh cukup tinggi saat diperiksa, penyebab kehujanan kemarin malam.','Istirahat di UKS','Demam',NULL),(9,9,'Tenggorokan gatal dan juga kering, saat meminta penjelasan lebih ternyata dalam 1 minggu Bima memang merasa kurang minum','Kembali melanjutkan aktivitas','Masalah Tenggorokan',NULL),(10,10,'Mata perih dan gatal, saat diperiksa sudah mulai bengkak walaupun tidak parah sekali.','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(11,11,'Perut sakit dan saat ditanyai lebih lanjut ia belum makan dari kemarin sore, karena tugas banyak dan kerjaan diluar rumah.','Istirahat di UKS','Sakit Perut',NULL),(12,12,'Mata merah untung belum membengkak. Dikarenakan debu masuk saaat bermain sepak bola','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(13,13,'Mata gatal saat diperiksa sudah mulai membengkak, disatu sisi kulit didekat mata juga memerah dan gatal, saat ditanya lebih lanjut ternyata ia baru ingat kalau sempat memakan udang, Alvin alegri udang dan itu membuat wajahnya gatal dan matapun juga gatal','Kembali melanjutkan aktivitas','Alergi',NULL),(14,14,'gatal gatal ditubuh dikarenakan alergi udang dan tidak sengaja memakannya tadi pagi.','Istirahat di UKS','Alergi',NULL),(15,15,'Tubuh terasa lemas dan ingin ambruk saat ditanya lebih lanjut ternyata kurang minum dan istirahat dalam kurun waktu satu minggu','Istirahat di UKS','Pusing',NULL),(16,16,'Mata sakit dan memerah setelah diusap, saat diperiksa ternyata mata sudah iritasi','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(17,17,'Sakit Tenggorokan dikarenakan kurang minum, tidak BAB selama satu minggu','Kembali melanjutkan aktivitas','Masalah Tenggorokan',NULL),(18,18,'Mata memerah saat sudah diperiksa untung saja belum parah dalam pembengkakan','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(19,19,'saat pasien diperiksa, mata sudah membengkak dan cukup dilevel yang mulai mengkawatirkan.','Istirahat di UKS','Iritasi Mata',NULL),(20,20,'Saat mata dicek, mata tidak membengkak seperti sebelumnya. Tetapi masih memerah diarea pojokan mata','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(21,21,'perlu datang ke bu endah','Kembali melanjutkan aktivitas','Pusing',NULL),(22,22,'Suhu 38,2°C, istirahat di UKS 30 menit, diminta banyak minum air putih','Istirahat di UKS','Demam',NULL),(23,23,'Saat ditanyai ternyata akhir ini kurang minum beruntung saja tidak ada demam','Kembali melanjutkan aktivitas','Batuk / Flu',NULL),(24,24,'Kemungkinan masuk angin / makanan kurang cocok','Kembali melanjutkan aktivitas','Sakit Perut',NULL),(25,25,'Mata memerah, untung tidak membengkak','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(26,26,'Disarankan ke dokter gigi sepulang sekolah','Kembali melanjutkan aktivitas','Sakit Gigi',NULL),(27,27,'Saat ditanyai lebih lanjut pasien belum sarapan, diminta makan dulu','Kembali melanjutkan aktivitas','Pusing',NULL),(28,28,'Sakit tenggorokan dan suara serak','Kembali melanjutkan aktivitas','Masalah Tenggorokan',NULL),(29,29,'Terlalu lama di depan komputer','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(30,30,'Saat ditanya lebih lanjut pasien belum makan sejak pagi','Istirahat di UKS','Sakit Perut',NULL),(31,31,'Saat ditanya lebih lanjut pasien mengalami tekanan kerja, disarankan istirahat sebentar','Istirahat di UKS','Tegang / Stres Ringan',NULL),(32,32,'Saat ditanyai lebih lanjut pasien sering meminum dan makan makanan sembarang dan saat diperiksa tidak mengalami demam','Kembali melanjutkan aktivitas','Batuk / Flu',NULL),(33,33,'Saat diperiksa ternyata jarang minum','Kembali melanjutkan aktivitas','Alergi',NULL),(34,34,'Luka karena tergores saat bekerja membersihkan barang','Kembali melanjutkan aktivitas','Luka Ringan',NULL),(35,35,'Saat ditanya kurang istirahat dan bekerja terus','Istirahat di UKS','Cedera',NULL),(36,36,'Saat diperiksa suhu 37,8°C','Dipulangkan','Demam',NULL),(37,39,'Mata memerah','Kembali melanjutkan aktivitas','Iritasi Mata',NULL),(38,41,'sakit perut','Kembali melanjutkan aktivitas','Sakit Perut',NULL),(39,42,'.','Istirahat di UKS','Pusing',NULL);
/*!40000 ALTER TABLE `pemeriksaan_klinis` ENABLE KEYS */;
