--
-- Table structure for table `t_siswa`
--

DROP TABLE IF EXISTS `t_siswa`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `t_siswa` (
  `NIS` char(15) NOT NULL,
  `NISN` char(25) DEFAULT NULL,
  `NIK` char(50) DEFAULT NULL,
  `NKK` char(50) DEFAULT NULL,
  `NAMA_SISWA` varchar(100) NOT NULL,
  `NAMA_PANGGILAN` varchar(50) DEFAULT NULL,
  `JENIS_KELAMIN` char(1) DEFAULT NULL COMMENT 'L / P',
  `TEMPAT_LAHIR` varchar(100) DEFAULT NULL,
  `TANGGAL_LAHIR` date DEFAULT NULL,
  `AGAMA` char(1) DEFAULT NULL,
  `KEWARGANEGARAAN` varchar(50) DEFAULT NULL,
  `ANAK_KE` char(2) DEFAULT NULL,
  `JML_SDR_KANDUNG` char(2) DEFAULT NULL,
  `JML_SDR_TIRI` char(2) DEFAULT NULL,
  `JML_SDR_ANGKAT` char(2) DEFAULT NULL,
  `STATUS_YATIM` char(2) DEFAULT NULL,
  `BAHASA` varchar(100) DEFAULT NULL,
  `ALAMAT_SISWA` text DEFAULT NULL,
  `NO_TELEPON` varchar(50) DEFAULT NULL,
  `TINGGAL` varbinary(100) DEFAULT NULL,
  `JARAK_TINGGAL` varchar(5) DEFAULT NULL,
  `WAKTU_TEMPUH` varchar(15) DEFAULT NULL,
  `GOL_DARAH` char(1) DEFAULT NULL,
  `RIWAYAT_SAKIT` varchar(100) DEFAULT NULL,
  `KELAINAN_JASMANI` varchar(100) DEFAULT NULL,
  `TINGGI_BADAN` decimal(4,1) DEFAULT NULL,
  `BERAT_BADAN` decimal(4,1) DEFAULT NULL,
  `LINGKAR_KEPALA` decimal(4,1) DEFAULT NULL,
  `ASAL_SEKOLAH` varchar(100) DEFAULT NULL,
  `IJAZAH_TANGGAL` date DEFAULT NULL,
  `IJAZAH_NOMOR` varchar(50) DEFAULT NULL,
  `LAMA_BELAJAR` char(2) DEFAULT NULL,
  `PINDAHAN_SMA` varchar(100) DEFAULT NULL,
  `PINDAHAN_ALASAN` varchar(100) DEFAULT NULL,
  `DITERIMA_TINGKAT` varchar(10) DEFAULT NULL,
  `DITERIMA_KELAS` varchar(10) DEFAULT NULL,
  `DITERIMA_TANGGAL` date DEFAULT NULL,
  `FOTO` varchar(100) DEFAULT NULL,
  `ID_USER` varchar(64) NOT NULL,
  `KAB_KOTA` varchar(100) DEFAULT NULL,
  `TANGGAL_AKSES` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`NIS`),
  UNIQUE KEY `t_siswa_indx` (`NIS`(10)) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

